import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

import { apiCandidateBases, fetchWithApiFallback } from '../api-fallback'

// Contrato (web#131, commit 2a7cfe6): zero hardcoded, zero default.
// Primária = VITE_URL_DATABASE/VITE_URL_FILES; fallbacks = VITE_API_FALLBACK_URLS.
// Env vazia = lista vazia. Os testes stubam import.meta.env direto.

function setEnv(key: string, value: string | undefined) {
  if (value === undefined) {
    delete (import.meta.env as Record<string, unknown>)[key]
  } else {
    ;(import.meta.env as Record<string, unknown>)[key] = value
  }
}

const fetchMock = vi.fn()

beforeEach(() => {
  fetchMock.mockReset()
  vi.stubGlobal('fetch', fetchMock)
  for (const key of ['VITE_URL_DATABASE', 'VITE_URL_FILES', 'VITE_API_TOKEN', 'VITE_API_FALLBACK_URLS']) {
    setEnv(key, undefined)
  }
})

afterEach(() => {
  vi.unstubAllGlobals()
})

describe('apiCandidateBases', () => {
  it('sem env nenhuma: lista vazia (falha cedo e explícita)', () => {
    expect(apiCandidateBases('database')).toEqual([])
  })

  it('só primária: lista com 1, sem fallback', () => {
    setEnv('VITE_URL_DATABASE', 'https://api.pianolouvorja.com.br/json_db')
    expect(apiCandidateBases('database')).toEqual(['https://api.pianolouvorja.com.br/json_db'])
  })

  it('primária + fallbacks: ordem preservada, sem duplicar host da primária', () => {
    setEnv('VITE_URL_DATABASE', 'https://api.pianolouvorja.com.br/json_db')
    setEnv(
      'VITE_API_FALLBACK_URLS',
      'https://api.pianolouvorja.com.br, https://api.louvorja.com.br ,https://api.louvorja.workers.dev/',
    )
    expect(apiCandidateBases('database')).toEqual([
      'https://api.pianolouvorja.com.br/json_db',
      'https://api.louvorja.com.br/json_db',
      'https://api.louvorja.workers.dev/json_db',
    ])
  })

  it('env de dev local (127.0.0.1) + fallbacks da env', () => {
    setEnv('VITE_URL_DATABASE', 'http://127.0.0.1:3100/json_db')
    setEnv('VITE_API_FALLBACK_URLS', 'https://api.louvorja.com.br')
    const bases = apiCandidateBases('database')
    expect(bases[0]).toBe('http://127.0.0.1:3100/json_db')
    expect(bases).toHaveLength(2)
  })

  it('fallbacks sozinhos (sem primária) entram como candidatas', () => {
    setEnv('VITE_API_FALLBACK_URLS', 'https://api.louvorja.com.br')
    expect(apiCandidateBases('files')).toEqual(['https://api.louvorja.com.br/file'])
  })
})

describe('fetchWithApiFallback', () => {
  it('primária ok: nem tenta fallback', async () => {
    setEnv('VITE_URL_DATABASE', 'https://api.pianolouvorja.com.br/json_db')
    fetchMock.mockResolvedValueOnce(new Response(JSON.stringify({ ok: 1 }), { status: 200 }))
    const { data, base } = await fetchWithApiFallback('database', 'pt_categories')
    expect(data).toEqual({ ok: 1 })
    expect(base).toBe('https://api.pianolouvorja.com.br/json_db')
    expect(fetchMock).toHaveBeenCalledTimes(1)
  })

  it('primária fora (rede) → cai pro fallback da env', async () => {
    setEnv('VITE_URL_DATABASE', 'https://api.pianolouvorja.com.br/json_db')
    setEnv('VITE_API_FALLBACK_URLS', 'https://api.louvorja.com.br')
    fetchMock
      .mockRejectedValueOnce(new TypeError('Failed to fetch'))
      .mockResolvedValueOnce(new Response(JSON.stringify({ ok: 2 }), { status: 200 }))
    const { data, base } = await fetchWithApiFallback('database', 'pt_categories', {
      retries: 0,
    })
    expect(data).toEqual({ ok: 2 })
    expect(base).toBe('https://api.louvorja.com.br/json_db')
  })

  it('primária e fallback 1 fora → fallback 2 atende', async () => {
    setEnv('VITE_URL_DATABASE', 'https://api.pianolouvorja.com.br/json_db')
    setEnv(
      'VITE_API_FALLBACK_URLS',
      'https://api.louvorja.com.br,https://api.louvorja.workers.dev',
    )
    fetchMock
      .mockRejectedValueOnce(new TypeError('Failed to fetch'))
      .mockRejectedValueOnce(new TypeError('Failed to fetch'))
      .mockResolvedValueOnce(new Response(JSON.stringify({ ok: 3 }), { status: 200 }))
    const { data, base } = await fetchWithApiFallback('database', 'pt_musics', {
      retries: 0,
    })
    expect(data).toEqual({ ok: 3 })
    expect(base).toBe('https://api.louvorja.workers.dev/json_db')
  })

  it('todas caídas: propaga o último erro', async () => {
    setEnv('VITE_URL_DATABASE', 'https://api.pianolouvorja.com.br/json_db')
    setEnv('VITE_API_FALLBACK_URLS', 'https://api.louvorja.com.br,https://api.louvorja.workers.dev')
    fetchMock.mockRejectedValue(new TypeError('Failed to fetch'))
    await expect(
      fetchWithApiFallback('database', 'pt_categories', { retries: 0 }),
    ).rejects.toThrow()
    expect(fetchMock).toHaveBeenCalledTimes(3)
  })

  it('404 definitivo na primária também migra de host (catálogo pode divergir)', async () => {
    setEnv('VITE_URL_DATABASE', 'https://api.pianolouvorja.com.br/json_db')
    setEnv('VITE_API_FALLBACK_URLS', 'https://api.louvorja.com.br')
    fetchMock
      .mockResolvedValueOnce(new Response('not found', { status: 404 }))
      .mockResolvedValueOnce(new Response(JSON.stringify({ ok: 9 }), { status: 200 }))
    const { data, base } = await fetchWithApiFallback('database', 'pt_categories', {
      retries: 0,
    })
    expect(data).toEqual({ ok: 9 })
    expect(base).toBe('https://api.louvorja.com.br/json_db')
  })

  it('sem env: rejeita cedo (nenhuma candidata)', async () => {
    await expect(
      fetchWithApiFallback('database', 'pt_categories', { retries: 0 }),
    ).rejects.toThrow()
    expect(fetchMock).not.toHaveBeenCalled()
  })
})

src/__tests__/integration/eula-flow.test.source:
import { mount } from '@vue/test-utils'
import { beforeEach, describe, expect, it, vi } from 'vitest'
import { createI18n } from 'vue-i18n'
import { createMemoryHistory, createRouter } from 'vue-router'

import ptBR from '@locales/pt-BR'

// --- Mocks ---

vi.mock('vuetify/components', () => ({
  VBtn: {
    name: 'VBtn',
    emits: ['click'],
    props: { variant: String, size: String, disabled: Boolean },
    template: '<button :disabled="disabled" @click="$emit(\'click\')"><slot /></button>',
  },
}))

vi.mock('@design-system/index', () => ({
  GlassCard: {
    name: 'GlassCard',
    template: '<div class="glass-card-stub"><slot /></div>',
  },
}))

vi.mock('../../../docs/LEGAL/eula/pt-BR.txt?raw', () => ({
  default: 'Mocked EULA text',
}))

import { _resetEulaState } from '@shared/composables/useEula'

// Router minimo para o teste de integracao
const HomeView = { template: '<div data-testid="home">Home Page</div>' }

const router = createRouter({
  history: createMemoryHistory(),
  routes: [{ path: '/', component: HomeView }],
})

const i18n = createI18n({
  legacy: false,
  locale: 'pt-BR',
  messages: { 'pt-BR': ptBR },
})

async function makeWrapper() {
  const App = (await import('@app/../App.vue')).default
  return mount(App, {
    global: {
      plugins: [router, i18n],
      stubs: {
        Teleport: { template: '<div class="teleport-stub"><slot /></div>' },
      },
    },
  })
}

describe('Integracao: App.vue + EulaDialog + useEula', () => {
  beforeEach(async () => {
    localStorage.clear()
    _resetEulaState()
    vi.restoreAllMocks()
    await router.push('/')
  })

  it('mostra EulaDialog e ESCONDE o router-view antes do aceite', async () => {
    const wrapper = await makeWrapper()
    await wrapper.vm.$nextTick()

    expect(wrapper.text()).toContain('Licença')
    expect(wrapper.find('[data-testid="home"]').exists()).toBe(false)
  })

  it('mostra router-view APOS aceitar o EULA', async () => {
    const wrapper = await makeWrapper()
    await wrapper.vm.$nextTick()

    // Simular aceite: rolar ate o fim e clicar Aceito
    const textArea = wrapper.find('[role="region"]')
    Object.defineProperty(textArea.element, 'scrollHeight', { configurable: true, value: 500 })
    Object.defineProperty(textArea.element, 'clientHeight', { configurable: true, value: 400 })
    Object.defineProperty(textArea.element, 'scrollTop', { configurable: true, value: 100 })
    await textArea.trigger('scroll')

    const acceptBtn = wrapper.findAll('button').find((b) => b.text().includes('Aceito'))
    await acceptBtn?.trigger('click')
    await wrapper.vm.$nextTick()

    // Agora o router-view deve aparecer
    expect(wrapper.find('[data-testid="home"]').exists()).toBe(true)
    expect(wrapper.text()).not.toContain('Licença')
  })

  it('persiste aceite: ao remontar, nao mostra EULA novamente', async () => {
    // Primeiro mount: aceitar
    const wrapper1 = await makeWrapper()
    await wrapper1.vm.$nextTick()

    const textArea = wrapper1.find('[role="region"]')
    Object.defineProperty(textArea.element, 'scrollHeight', { configurable: true, value: 500 })
    Object.defineProperty(textArea.element, 'clientHeight', { configurable: true, value: 400 })
    Object.defineProperty(textArea.element, 'scrollTop', { configurable: true, value: 100 })
    await textArea.trigger('scroll')

    const acceptBtn = wrapper1.findAll('button').find((b) => b.text().includes('Aceito'))
    await acceptBtn?.trigger('click')

    // Reset do estado do modulo para simular reload
    _resetEulaState()

    // Segundo mount: ja aceito
    const wrapper2 = await makeWrapper()
    await wrapper2.vm.$nextTick()

    expect(wrapper2.text()).not.toContain('Licença')
    expect(wrapper2.find('[data-testid="home"]').exists()).toBe(true)
  })

  it('fluxo completo de recusa: recusar > confirmar > tela de saida', async () => {
    const wrapper = await makeWrapper()
    await wrapper.vm.$nextTick()

    // Clicar Nao aceito
    const declineBtn = wrapper.findAll('button').find((b) => b.text().includes('Não aceito'))
    await declineBtn?.trigger('click')
    await wrapper.vm.$nextTick()

    expect(wrapper.text()).toContain('Tem certeza?')

    // Clicar Sim, recusar
    const confirmBtn = wrapper.findAll('button').find((b) => b.text().includes('Sim, recusar'))
    await confirmBtn?.trigger('click')
    await wrapper.vm.$nextTick()

    expect(wrapper.text()).toContain('não aceitou')
    expect(wrapper.find('[data-testid="home"]').exists()).toBe(false)

    // Verificar que localStorage foi limpo
    expect(localStorage.getItem('eula_accepted_v1')).toBeNull()
  })

  it('aceite e depois recusa (via nova sessao) volta a mostrar EULA', async () => {
    // Sessao 1: aceitar
    localStorage.setItem('eula_accepted_v1', 'true')
    _resetEulaState()

    const wrapper1 = await makeWrapper()
    await wrapper1.vm.$nextTick()
    expect(wrapper1.find('[data-testid="home"]').exists()).toBe(true)

    // Simular limpeza (usuario limpou dados do site)
    localStorage.clear()
    _resetEulaState()

    // Sessao 2: EULA aparece de novo
    const wrapper2 = await makeWrapper()
    await wrapper2.vm.$nextTick()
    expect(wrapper2.text()).toContain('Licença')
  })
})

